test-code.code:
import com.google.gson.Gson

class Foo {
    fun toJson(obj: Any): String {
        return Gson().toJson(obj) // bad
    }
}

import com.google.gson.GsonBuilder

class Foo {
    fun toJson(obj: Any): String {
        val gson = GsonBuilder()
            .create() // bad
        return gson.toJson(obj)
    }
}

import com.google.gson.Gson

class Foo {
    companion object {
        private val GSON = Gson() // good - companion object val, created once
    }
    fun toJson(obj: Any): String = GSON.toJson(obj)
}

import com.google.gson.Gson

class Foo {
    fun process(items: List<Any>): List<String> =
        items.map {
            Gson().toJson(it) // bad - Gson created per lambda invocation
        }
}
